import"./chunk-VC46IEJQ.js";var e=(a,o,s,i,d,r,n,h,t)=>({name:{en:a[0],zh:a[1]},desc:{en:o[0],zh:o[1]},tour:{en:s[0],zh:s[1]},...t?{spoiler:{en:t[0],zh:t[1]}}:{},source:{confidence:i,refs:d,book:{en:r[0],zh:r[1]},unknown:{en:n[0],zh:n[1]},interpretation:{en:h[0],zh:h[1]}}}),l={id:"castle-black",intro:{en:"The headquarters of the Night's Watch huddles at the foot of the Wall, a seven-hundred-foot cliff of ice running out of sight east and west. Castle Black has no curtain wall of its own; many of its towers stand empty or half ruined, and the Haunted Forest begins beyond the gate.",zh:"\u5B88\u591C\u4EBA\u7684\u603B\u90E8\u8737\u7F29\u5728\u957F\u57CE\u811A\u4E0B\u3002\u8FD9\u9053\u4E03\u767E\u5C3A\u9AD8\u7684\u51B0\u5D16\u5411\u4E1C\u897F\u4E24\u5934\u5EF6\u4F38\uFF0C\u76F4\u81F3\u671B\u4E0D\u89C1\u7684\u8FDC\u65B9\u3002\u9ED1\u57CE\u5821\u672C\u8EAB\u6CA1\u6709\u57CE\u5899\uFF0C\u8BB8\u591A\u5854\u697C\u65E9\u5DF2\u7A7A\u7F6E\u6216\u534A\u6210\u5E9F\u589F\uFF1B\u7A7F\u8FC7\u57CE\u95E8\uFF0C\u4FBF\u662F\u9B3C\u5F71\u68EE\u6797\u3002"},notes:{en:"From the novels: the Wall's height and ice, the tunnel and its gates, the ice cells, the switchback stair and the winch cage, a half-ruined Castle Black with the named towers and halls below, the Gift to the south and the Haunted Forest to the north. Invented here: the layout, building shapes and sizes, the number of stair flights and all surface detail.",zh:"\u51FA\u81EA\u5C0F\u8BF4\uFF1A\u957F\u57CE\u7684\u9AD8\u5EA6\u4E0E\u51B0\u4F53\u3001\u7A7F\u5899\u96A7\u9053\u53CA\u95F8\u95E8\u3001\u51B0\u7262\u3001\u4E4B\u5B57\u5F62\u6728\u68AF\u4E0E\u7EDE\u76D8\u540A\u7B3C\u3001\u534A\u5DF2\u8352\u5E9F\u7684\u9ED1\u57CE\u5821\u53CA\u4E0B\u5217\u5404\u5854\u697C\u5385\u5802\u3001\u5357\u9762\u7684\u8D60\u5730\u4E0E\u5317\u9762\u7684\u9B3C\u5F71\u68EE\u6797\u3002\u672C\u573A\u666F\u81EA\u884C\u8BBE\u8BA1\uFF1A\u6574\u4F53\u5E03\u5C40\u3001\u5EFA\u7B51\u9020\u578B\u4E0E\u5C3A\u5BF8\u3001\u6728\u68AF\u6298\u6570\u53CA\u4E00\u5207\u8868\u9762\u7EC6\u8282\u3002"},tour:["the-wall","wall-gate","winch-lift","wall-stairs","lord-commanders-tower","commanders-keep","kings-tower","hardins-tower","armory","shield-hall","ravenry","stables","haunted-forest","kingsroad-gift"],sources:[{ref:"agot",checked:"memory",note:{en:"Jon's arrival, the Wall's size, the cage, Maester Aemon's rookery and the fire in the Lord Commander's Tower; recalled, not re-read.",zh:"\u743C\u6069\u521D\u5230\u957F\u57CE\u3001\u957F\u57CE\u7684\u89C4\u6A21\u3001\u540A\u7B3C\u3001\u4F0A\u8499\u5B66\u58EB\u7684\u9E26\u5DE2\uFF0C\u4EE5\u53CA\u603B\u53F8\u4EE4\u5854\u7684\u90A3\u573A\u706B\uFF1B\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"asos",checked:"memory",note:{en:"The defence of Castle Black: the King's Tower, the tunnel and the stair; recalled.",zh:"\u9ED1\u57CE\u5821\u4FDD\u536B\u6218\uFF1A\u56FD\u738B\u5854\u3001\u96A7\u9053\u4E0E\u6728\u68AF\uFF1B\u51ED\u8BB0\u5FC6\u3002"}},{ref:"adwd",checked:"memory",note:{en:"Castle Black under its new Lord Commander: the Shieldhall, the ice cells, the rooms behind the armory; recalled.",zh:"\u65B0\u4EFB\u603B\u53F8\u4EE4\u6CBB\u4E0B\u7684\u9ED1\u57CE\u5821\uFF1A\u76FE\u5385\u3001\u51B0\u7262\u3001\u6B66\u5668\u5E93\u540E\u7684\u5C45\u5BA4\uFF1B\u51ED\u8BB0\u5FC6\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Search summaries of the wiki: the fire that gutted the Lord Commander's Tower, the move to the King's Tower, the abandoned Shieldhall, Hardin's Tower and the armory. The pages themselves could not be fetched.",zh:"\u7EF4\u57FA\u7684\u641C\u7D22\u6458\u8981\uFF1A\u711A\u6BC1\u603B\u53F8\u4EE4\u5854\u7684\u5927\u706B\u3001\u603B\u53F8\u4EE4\u8FC1\u5C45\u56FD\u738B\u5854\u3001\u5E9F\u5F03\u7684\u76FE\u5385\u3001\u54C8\u4E01\u5854\u4E0E\u6B66\u5668\u5E93\u3002\u9875\u9762\u672C\u8EAB\u65E0\u6CD5\u6293\u53D6\u3002"}}],landmarks:{"the-wall":e(["The Wall","\u957F\u57CE"],["A wall of ice some seven hundred feet high, running about three hundred miles from shore to shore. Here its face shows slumped ledges, melt streaks and icicles.","\u9AD8\u7EA6\u4E03\u767E\u5C3A\u7684\u51B0\u5899\uFF0C\u4E1C\u897F\u6A2A\u8D2F\u7EA6\u4E09\u767E\u91CC\uFF0C\u4ECE\u6D77\u5CB8\u76F4\u62B5\u6D77\u5CB8\u3002\u6B64\u5904\u53EF\u89C1\u574D\u843D\u7684\u51B0\u53F0\u3001\u878D\u6C34\u75D5\u8FF9\u4E0E\u51B0\u51CC\u3002"],["The Wall: seven hundred feet of ice between the realm and whatever lies beyond.","\u957F\u57CE\uFF1A\u4E03\u767E\u5C3A\u575A\u51B0\uFF0C\u9694\u5F00\u738B\u56FD\u4E0E\u5899\u5916\u7684\u4E00\u5207\u3002"],"high",["agot","twoiaf"],["About 700 ft high and about 300 miles long, made of ice; the top is weathered and cracked.","\u9AD8\u7EA6\u4E03\u767E\u5C3A\uFF0C\u957F\u7EA6\u4E09\u767E\u91CC\uFF0C\u4EE5\u51B0\u7B51\u6210\uFF1B\u9876\u90E8\u98CE\u5316\u5F00\u88C2\u3002"],["Its thickness, and what the ice really looks like along its length.","\u539A\u5EA6\uFF0C\u4EE5\u53CA\u5404\u6BB5\u51B0\u9762\u7684\u771F\u5B9E\u6837\u8C8C\u3002"],["A segmented, slightly bowed wall with a translucent skin; the thickness (about 30 m) is invented.","\u5206\u6BB5\u4E14\u7565\u5E26\u5F27\u5EA6\u7684\u51B0\u5899\uFF0C\u8868\u5C42\u534A\u900F\u660E\uFF1B\u7EA6\u4E09\u5341\u7C73\u7684\u539A\u5EA6\u4E3A\u81EA\u62DF\u3002"],["Later books suggest that old spells woven into the ice keep certain dead things from passing.","\u540E\u7EED\u5377\u4E2D\u6697\u793A\uFF0C\u51B0\u4E2D\u7EC7\u6709\u53E4\u8001\u7684\u5492\u8BED\uFF0C\u80FD\u963B\u6321\u67D0\u4E9B\u6B7B\u7269\u901A\u8FC7\u3002"]),"wall-gate":e(["Tunnel Gate","\u96A7\u9053\u57CE\u95E8"],["A narrow, crooked tunnel through the foot of the Wall, closed by gates of oak and iron. A cutaway shows the tunnel and the ice cells beside it.","\u4E00\u6761\u72ED\u7A84\u66F2\u6298\u7684\u96A7\u9053\u7A7F\u8FC7\u957F\u57CE\u5E95\u90E8\uFF0C\u4EE5\u6A61\u6728\u4E0E\u94C1\u94F8\u7684\u95F8\u95E8\u5C01\u95ED\u3002\u53EF\u6253\u5F00\u5256\u9762\u67E5\u770B\u96A7\u9053\u53CA\u65C1\u8FB9\u7684\u51B0\u7262\u3002"],["The only way through the Wall here runs beneath seven hundred feet of ice.","\u6B64\u5904\u7A7F\u8D8A\u957F\u57CE\u7684\u552F\u4E00\u901A\u8DEF\uFF0C\u4ECE\u4E03\u767E\u5C3A\u575A\u51B0\u4E4B\u4E0B\u7ECF\u8FC7\u3002"],"medium",["agot","asos","adwd"],["A tunnel with gates runs through the Wall; cells cut into the ice at its base hold stores and prisoners.","\u957F\u57CE\u5E95\u90E8\u6709\u8BBE\u95F8\u95E8\u7684\u96A7\u9053\uFF1B\u5899\u811A\u51FF\u51FA\u7684\u51B0\u7262\u7528\u6765\u50A8\u7269\u6216\u5173\u62BC\u72AF\u4EBA\u3002"],["How many gates there are and how the cells are laid out.","\u95F8\u95E8\u6570\u91CF\u4E0E\u51B0\u7262\u5E03\u5C40\u3002"],["Three iron gates, five cell doors and a straight passage are invented.","\u4E09\u9053\u94C1\u95F8\u3001\u4E94\u6247\u7262\u95E8\u4E0E\u7B14\u76F4\u7684\u901A\u9053\u5747\u4E3A\u81EA\u62DF\u3002"],["In the third book the tunnel is the scene of a desperate defence.","\u7B2C\u4E09\u5377\u4E2D\uFF0C\u8FD9\u6761\u96A7\u9053\u4E0A\u6F14\u4E86\u4E00\u573A\u6B8A\u6B7B\u7684\u9632\u5B88\u3002"]),"winch-lift":e(["The Cage","\u540A\u7B3C"],["An iron cage hauled up and down the south face of the Wall by a great winch at the top.","\u4E00\u53EA\u94C1\u7B3C\uFF0C\u7531\u5899\u9876\u7684\u5927\u7EDE\u76D8\u7275\u5F15\uFF0C\u6CBF\u957F\u57CE\u5357\u9762\u4E0A\u4E0B\u5347\u964D\u3002"],["Riders of the cage reach the top far faster than climbers on the stair.","\u4E58\u540A\u7B3C\u767B\u9876\uFF0C\u6BD4\u6CBF\u6728\u68AF\u6500\u722C\u5FEB\u5F97\u591A\u3002"],"high",["agot"],["A winch-drawn cage carries men and supplies up the Wall; Jon rides it to the top.","\u7EDE\u76D8\u7275\u5F15\u7684\u540A\u7B3C\u628A\u4EBA\u5458\u4E0E\u7269\u8D44\u8FD0\u4E0A\u5899\u9876\uFF1B\u743C\u6069\u66FE\u4E58\u5B83\u767B\u9876\u3002"],["Its exact construction and how it is anchored.","\u5177\u4F53\u6784\u9020\u4E0E\u56FA\u5B9A\u65B9\u5F0F\u3002"],["A timber frame beside the stair with an animated cage stands for it.","\u4EE5\u6728\u68AF\u65C1\u7684\u6728\u67B6\u548C\u4E00\u53EA\u4F1A\u5347\u964D\u7684\u7B3C\u5B50\u6765\u8868\u73B0\u3002"]),"wall-stairs":e(["The Great Stair","\u957F\u6728\u68AF"],["A switchback stair of timber clinging to the Wall, flight after flight to the top.","\u8D34\u7740\u51B0\u5899\u4E4B\u5B57\u5F62\u6298\u8FD4\u7684\u6728\u68AF\uFF0C\u4E00\u6BB5\u63A5\u4E00\u6BB5\u901A\u5411\u5899\u9876\u3002"],["The wooden stair zigzags up the ice like a frozen bolt of lightning.","\u6728\u68AF\u5728\u51B0\u9762\u4E0A\u66F2\u6298\u800C\u4E0A\uFF0C\u5B9B\u5982\u4E00\u9053\u51BB\u4F4F\u7684\u95EA\u7535\u3002"],"high",["agot","asos"],["A great wooden switchback stair climbs the south face; it is treacherous in ice and wind.","\u4E00\u9053\u5DE8\u5927\u7684\u4E4B\u5B57\u5F62\u6728\u68AF\u6CBF\u5357\u9762\u6500\u5347\uFF1B\u7ED3\u51B0\u8D77\u98CE\u65F6\u5341\u5206\u51F6\u9669\u3002"],["The number of flights and its exact course.","\u6298\u6570\u4E0E\u786E\u5207\u8D70\u5411\u3002"],["Seven flights east of the gate, propped on posts.","\u57CE\u95E8\u4E1C\u4FA7\u4E03\u6BB5\u6728\u68AF\uFF0C\u4E0B\u4EE5\u7ACB\u67F1\u652F\u6491\u3002"],["In the third book much of the stair is destroyed during the fighting.","\u7B2C\u4E09\u5377\u7684\u6218\u6597\u4E2D\uFF0C\u6728\u68AF\u5927\u534A\u88AB\u6BC1\u3002"]),"lord-commanders-tower":e(["Lord Commander's Tower","\u603B\u53F8\u4EE4\u5854"],["The Lord Commander's residence, with vaults beneath it; fire later gutted its upper floors.","\u603B\u53F8\u4EE4\u7684\u5C45\u6240\uFF0C\u5854\u4E0B\u6709\u5730\u7A96\uFF1B\u540E\u6765\u4E00\u573A\u5927\u706B\u70E7\u7A7A\u4E86\u4E0A\u9762\u51E0\u5C42\u3002"],["The Lord Commander's Tower: still standing, but scorched inside.","\u603B\u53F8\u4EE4\u5854\uFF1A\u5854\u8EAB\u72B9\u5728\uFF0C\u91CC\u9762\u5374\u5DF2\u70E7\u5F97\u7126\u9ED1\u3002"],"high",["agot","asos","adwd","awoiaf"],["Mormont lives here in the first book until a fire guts the top two floors; afterwards the Lord Commander lodges elsewhere and the undervault is still used.","\u7B2C\u4E00\u5377\u4E2D\u83AB\u5C14\u8499\u4F4F\u5728\u6B64\u5854\uFF0C\u76F4\u5230\u4E00\u573A\u706B\u70E7\u7A7A\u4E86\u9876\u90E8\u4E24\u5C42\uFF1B\u6B64\u540E\u603B\u53F8\u4EE4\u79FB\u5C45\u522B\u5904\uFF0C\u5854\u4E0B\u5730\u7A96\u4ECD\u5728\u4F7F\u7528\u3002"],["Its height, shape and exact position.","\u9AD8\u5EA6\u3001\u5F62\u5236\u4E0E\u786E\u5207\u4F4D\u7F6E\u3002"],["A tall round stone tower with a conical roof, placed near the Wall.","\u5E26\u9525\u5F62\u9876\u7684\u9AD8\u5927\u5706\u5F62\u77F3\u5854\uFF0C\u7D27\u90BB\u957F\u57CE\u3002"]),"commanders-keep":e(["Burned Upper Floors","\u711A\u6BC1\u7684\u4E0A\u5C42"],["A squat stone block with charred, roofless upper storeys, standing for the fire damage to the Lord Commander's quarters.","\u4E00\u5EA7\u77EE\u58EE\u7684\u77F3\u697C\uFF0C\u4E0A\u5C42\u7126\u9ED1\u65E0\u9876\uFF0C\u7528\u4EE5\u8868\u73B0\u603B\u53F8\u4EE4\u5C45\u6240\u906D\u53D7\u7684\u706B\u707E\u3002"],["Charred stone recalls the night fire swept the Lord Commander's rooms.","\u7126\u9ED1\u7684\u77F3\u5899\uFF0C\u8BB0\u7740\u5927\u706B\u5E2D\u5377\u603B\u53F8\u4EE4\u5C45\u5BA4\u7684\u90A3\u4E00\u591C\u3002"],"low",["agot","awoiaf"],[`The books describe fire gutting the upper floors of the Lord Commander's Tower; they name no separate "Commander's Keep".`,"\u4E66\u4E2D\u5199\u5230\u5927\u706B\u70E7\u7A7A\u4E86\u603B\u53F8\u4EE4\u5854\u7684\u4E0A\u5C42\uFF0C\u4F46\u5E76\u6CA1\u6709\u4E00\u5EA7\u5355\u72EC\u7684\u201C\u603B\u53F8\u4EE4\u5821\u201D\u3002"],["Everything about this building as a separate structure.","\u628A\u5B83\u5F53\u4F5C\u72EC\u7ACB\u5EFA\u7B51\u7684\u4E00\u5207\u7EC6\u8282\u3002"],["The scene shows the fire damage as a separate gutted block beside the tower; this is a visual device, not a building from the books.","\u573A\u666F\u628A\u706B\u707E\u75D5\u8FF9\u753B\u6210\u5854\u65C1\u4E00\u5EA7\u88AB\u70E7\u7A7A\u7684\u72EC\u7ACB\u77F3\u697C\uFF0C\u8FD9\u53EA\u662F\u89C6\u89C9\u624B\u6CD5\uFF0C\u5E76\u975E\u4E66\u4E2D\u5EFA\u7B51\u3002"]),"kings-tower":e(["King's Tower","\u56FD\u738B\u5854"],["A tower named for royal guests, still roofed and sound while much around it decays.","\u4EE5\u738B\u5BA4\u8D35\u5BBE\u547D\u540D\u7684\u5854\u697C\uFF0C\u5468\u906D\u591A\u5DF2\u7834\u8D25\uFF0C\u5B83\u5374\u5C4B\u9876\u5B8C\u597D\u3001\u5899\u4F53\u575A\u56FA\u3002"],["The King's Tower was built for royal visitors, though kings seldom come.","\u56FD\u738B\u5854\u4E3A\u738B\u5BA4\u6765\u5BA2\u800C\u5EFA\uFF0C\u53EA\u662F\u56FD\u738B\u96BE\u5F97\u5149\u4E34\u3002"],"medium",["asos","adwd","awoiaf"],["A sound tower kept for distinguished guests; after the fire the Lord Commander lodges here, and its top serves as a fighting platform during the attack on the castle.","\u4E3A\u8D35\u5BBE\u4FDD\u7559\u7684\u575A\u56FA\u5854\u697C\uFF1B\u706B\u707E\u540E\u603B\u53F8\u4EE4\u66FE\u8FC1\u5C45\u4E8E\u6B64\uFF0C\u57CE\u5821\u9047\u88AD\u65F6\u5854\u9876\u8FD8\u88AB\u7528\u4F5C\u4F5C\u6218\u5E73\u53F0\u3002"],["Its shape and exact position.","\u5F62\u72B6\u4E0E\u786E\u5207\u4F4D\u7F6E\u3002"],["A tall square tower with a pyramid roof on the west side of the yard.","\u9662\u897F\u4E00\u5EA7\u65B9\u5F62\u9AD8\u5854\uFF0C\u5E26\u56DB\u5761\u5C16\u9876\u3002"],["In the fifth book a royal claimant takes up residence here.","\u7B2C\u4E94\u5377\u4E2D\uFF0C\u4E00\u4F4D\u738B\u4F4D\u4E89\u593A\u8005\u5165\u4F4F\u6B64\u5854\u3002"]),"hardins-tower":e(["Hardin's Tower","\u54C8\u4E01\u5854"],["A tower that leans so badly it looks ready to fall, its battlement broken and fallen stones littering the yard.","\u5854\u8EAB\u6B6A\u659C\u5F97\u4EFF\u4F5B\u968F\u65F6\u4F1A\u5012\uFF0C\u579B\u53E3\u6B8B\u7F3A\uFF0C\u5760\u843D\u7684\u77F3\u5757\u6563\u843D\u9662\u4E2D\u3002"],["Hardin's Tower leans as if the next gale might finish it.","\u54C8\u4E01\u5854\u6B6A\u6B6A\u659C\u659C\uFF0C\u597D\u50CF\u518D\u6765\u4E00\u9635\u5927\u98CE\u5C31\u4F1A\u5012\u584C\u3002"],"high",["agot","awoiaf"],["Described as leaning, with a broken battlement and fallen stones; recruits sleep there.","\u4E66\u4E2D\u63CF\u5199\u5B83\u503E\u659C\u6B32\u5012\u3001\u579B\u53E3\u6B8B\u7834\u3001\u788E\u77F3\u6EE1\u5730\uFF1B\u65B0\u5175\u5C31\u4F4F\u5728\u91CC\u9762\u3002"],["Its height and why it leans.","\u9AD8\u5EA6\u4E0E\u503E\u659C\u7684\u539F\u56E0\u3002"],["A tall square tower with a lean, a snapped crown and a rubble apron.","\u4E00\u5EA7\u503E\u659C\u7684\u65B9\u5F62\u9AD8\u5854\uFF0C\u5854\u9876\u6298\u65AD\uFF0C\u811A\u4E0B\u4E00\u5708\u788E\u77F3\u3002"]),armory:e(["Armory","\u6B66\u5668\u5E93"],["A long, low building with a forge, where the Watch's arms are made, mended and stored.","\u8BBE\u6709\u953B\u7089\u7684\u4F4E\u77EE\u957F\u5C4B\uFF0C\u5B88\u591C\u4EBA\u7684\u5175\u5668\u5728\u6B64\u6253\u9020\u3001\u4FEE\u8865\u4E0E\u5B58\u653E\u3002"],["Smoke from the forge shows the armory still works.","\u953B\u7089\u5192\u7740\u70DF\uFF0C\u8BF4\u660E\u6B66\u5668\u5E93\u4ECD\u5728\u8FD0\u8F6C\u3002"],"high",["agot","adwd","awoiaf"],["The armory has a forge run by the Watch's smith; rooms behind it later serve as the Lord Commander's quarters.","\u6B66\u5668\u5E93\u8BBE\u6709\u953B\u7089\uFF0C\u7531\u5B88\u591C\u4EBA\u7684\u94C1\u5320\u638C\u7BA1\uFF1B\u5176\u540E\u7684\u5C45\u5BA4\u540E\u6765\u6210\u4E86\u603B\u53F8\u4EE4\u7684\u4F4F\u5904\u3002"],["Its exact position and construction.","\u786E\u5207\u4F4D\u7F6E\u4E0E\u6784\u9020\u3002"],["Placed in the centre of the yard, with a chimney.","\u7F6E\u4E8E\u9662\u843D\u4E2D\u592E\uFF0C\u5E26\u4E00\u6839\u70DF\u56F1\u3002"]),"shield-hall":e(["Shieldhall","\u76FE\u5385"],["A large old hall where the Watch's knights once dined apart; long disused, it can hold hundreds.","\u4E00\u5EA7\u53E4\u8001\u7684\u5927\u5385\uFF0C\u6614\u65E5\u5B88\u591C\u4EBA\u4E2D\u7684\u9A91\u58EB\u5728\u6B64\u5355\u72EC\u7528\u81B3\uFF1B\u5982\u4ECA\u4E45\u5DF2\u5F03\u7F6E\uFF0C\u5374\u4ECD\u80FD\u5BB9\u7EB3\u6570\u767E\u4EBA\u3002"],["The Shieldhall stands empty, a relic of a larger Watch.","\u76FE\u5385\u7A7A\u7A7A\u8361\u8361\uFF0C\u662F\u5B88\u591C\u4EBA\u6614\u65E5\u4EBA\u4E01\u5174\u65FA\u7684\u9057\u8FF9\u3002"],"medium",["adwd","awoiaf"],["A feast hall abandoned as the Watch dwindled; the brothers now eat in the common hall. It is reopened for a large gathering in the fifth book.","\u968F\u7740\u5B88\u591C\u4EBA\u65E5\u6E10\u51CB\u96F6\u800C\u5E9F\u5F03\u7684\u5BB4\u4F1A\u5385\uFF1B\u5982\u4ECA\u5144\u5F1F\u4EEC\u6539\u5728\u516C\u5171\u98DF\u5802\u7528\u9910\u3002\u7B2C\u4E94\u5377\u4E2D\u5B83\u91CD\u65B0\u5F00\u653E\uFF0C\u7528\u4E8E\u4E00\u6B21\u5927\u578B\u96C6\u4F1A\u3002"],["Its size and exact form.","\u89C4\u6A21\u4E0E\u5177\u4F53\u5F62\u5236\u3002"],["A big gabled timber hall on the east side.","\u4E1C\u4FA7\u4E00\u5EA7\u5E26\u5C71\u5899\u7684\u5927\u578B\u6728\u6784\u5385\u5802\u3002"],["In the fifth book the Lord Commander addresses the assembled brothers and free folk here.","\u7B2C\u4E94\u5377\u4E2D\uFF0C\u603B\u53F8\u4EE4\u5728\u6B64\u5411\u5B88\u591C\u4EBA\u5144\u5F1F\u4E0E\u81EA\u7531\u6C11\u53D1\u8868\u8BB2\u8BDD\u3002"]),ravenry:e(["Rookery","\u9E26\u5DE2"],["The maester's wooden keep beneath the rookery, where the message ravens are kept.","\u5B66\u58EB\u6240\u5C45\u7684\u6728\u697C\uFF0C\u4E0A\u65B9\u4FBF\u662F\u9E26\u5DE2\uFF0C\u4F20\u4FE1\u7684\u6E21\u9E26\u5C31\u517B\u5728\u90A3\u91CC\u3002"],["Ravens come and go from the rookery above the maester's rooms.","\u6E21\u9E26\u5728\u5B66\u58EB\u5C45\u5BA4\u4E0A\u65B9\u7684\u9E26\u5DE2\u91CC\u8FDB\u8FDB\u51FA\u51FA\u3002"],"high",["agot","acok"],["Maester Aemon lives in a wooden keep below the rookery, where the ravens are kept.","\u4F0A\u8499\u5B66\u58EB\u4F4F\u5728\u9E26\u5DE2\u4E0B\u65B9\u7684\u6728\u697C\u91CC\uFF0C\u6E21\u9E26\u5C31\u517B\u5728\u697C\u4E0A\u3002"],["Its exact location and size.","\u786E\u5207\u4F4D\u7F6E\u4E0E\u89C4\u6A21\u3002"],["Stone footing, a timber loft and circling birds.","\u77F3\u780C\u57FA\u5EA7\u3001\u6728\u9020\u9601\u697C\uFF0C\u7FA4\u9E26\u76D8\u65CB\u3002"]),stables:e(["Stables","\u9A6C\u53A9"],["Long timber barns for the garrison's horses and mules.","\u4E3A\u5B88\u519B\u9A6C\u5339\u4E0E\u9AA1\u5B50\u642D\u5EFA\u7684\u957F\u6761\u6728\u68DA\u3002"],["Horses and mules for the rangers wait behind the yard.","\u6E38\u9A91\u5175\u7684\u9A6C\u4E0E\u9AA1\uFF0C\u5C31\u62F4\u5728\u9662\u5B50\u540E\u9762\u3002"],"medium",["agot"],["Castle Black keeps horses and garrons for its rangers; the stables are not described in detail.","\u9ED1\u57CE\u5821\u4E3A\u6E38\u9A91\u5175\u9972\u517B\u9A6C\u5339\u4E0E\u77EE\u79CD\u9A6C\uFF1B\u4E66\u4E2D\u672A\u8BE6\u8FF0\u9A6C\u53A9\u3002"],["Their position and number.","\u4F4D\u7F6E\u4E0E\u6570\u91CF\u3002"],["Two barns west of the yard.","\u9662\u897F\u4E24\u5EA7\u9A6C\u68DA\u3002"]),"haunted-forest":e(["Haunted Forest","\u9B3C\u5F71\u68EE\u6797"],["Dense, snow-laden forest beyond the Wall, dark and deep, crossed by a thin track.","\u957F\u57CE\u4EE5\u5317\u7684\u5BC6\u6797\uFF0C\u79EF\u96EA\u538B\u679D\uFF0C\u5E7D\u6DF1\u660F\u6697\uFF0C\u53EA\u6709\u4E00\u6761\u5C0F\u5F84\u7A7F\u8FC7\u3002"],["Beyond the gate lies the Haunted Forest, where rangers ride and not all return.","\u57CE\u95E8\u4E4B\u5916\u4FBF\u662F\u9B3C\u5F71\u68EE\u6797\uFF1B\u6E38\u9A91\u5175\u51FA\u5165\u5176\u95F4\uFF0C\u5E76\u975E\u4EBA\u4EBA\u90FD\u80FD\u5F52\u6765\u3002"],"high",["agot","acok"],["A vast forest north of the Wall, where the rangers scout.","\u957F\u57CE\u4EE5\u5317\u7684\u5E7F\u88A4\u68EE\u6797\uFF0C\u6E38\u9A91\u5175\u5728\u6B64\u5DE1\u5BDF\u3002"],["Its extent and the mix of trees.","\u8303\u56F4\u4E0E\u6811\u79CD\u6784\u6210\u3002"],["Pine and ironwood stand-ins, with one weirwood added.","\u4EE5\u677E\u6811\u548C\u94C1\u6728\u4E3A\u4EE3\u8868\uFF0C\u53E6\u6DFB\u4E00\u682A\u9C7C\u6881\u6728\u3002"]),"kingsroad-gift":e(["Kingsroad & the Gift","\u56FD\u738B\u5927\u9053\u4E0E\u8D60\u5730"],["The kingsroad runs north to the Wall through the Gift, the land south of the Wall granted to the Watch.","\u56FD\u738B\u5927\u9053\u5411\u5317\u7A7F\u8FC7\u8D60\u5730\u76F4\u62B5\u957F\u57CE\uFF1B\u8D60\u5730\u5373\u957F\u57CE\u4EE5\u5357\u8D50\u4E88\u5B88\u591C\u4EBA\u7684\u571F\u5730\u3002"],["The kingsroad ends at the Wall, across the half-empty Gift.","\u56FD\u738B\u5927\u9053\u7A7F\u8FC7\u4EBA\u70DF\u7A00\u5C11\u7684\u8D60\u5730\uFF0C\u6B62\u4E8E\u957F\u57CE\u3002"],"high",["agot","twoiaf"],["The kingsroad ends at Castle Black; the lands to the south are the Gift, granted to the Watch long ago and now thinly peopled.","\u56FD\u738B\u5927\u9053\u7684\u7EC8\u70B9\u662F\u9ED1\u57CE\u5821\uFF1B\u5176\u5357\u7684\u571F\u5730\u5373\u8D60\u5730\uFF0C\u5F88\u65E9\u4FBF\u8D50\u7ED9\u4E86\u5B88\u591C\u4EBA\uFF0C\u5982\u4ECA\u4EBA\u70DF\u7A00\u5C11\u3002"],["Settlements along the road and its exact course.","\u6CBF\u9014\u805A\u843D\u4E0E\u9053\u8DEF\u7684\u786E\u5207\u8D70\u5411\u3002"],["A winding road through sparse pine woods; no villages shown.","\u4E00\u6761\u5728\u7A00\u758F\u677E\u6797\u95F4\u873F\u8712\u7684\u9053\u8DEF\uFF0C\u4E0D\u753B\u6751\u843D\u3002"])}};export{l as default};
